public class MiniBucketInspector {
    private static final int CAPACITY = 16; // Standard initial capacity

    public static int calculateBucket(String key) {
        if (key == null) return 0;
        int h = key.hashCode();
        // Java HashMap spreading function: h ^ (h >>> 16)
        int spreadHash = h ^ (h >>> 16);
        // Bitmask indexing: (n - 1) & hash
        return (CAPACITY - 1) & spreadHash;
    }

    public static void main(String[] args) {
        String[] keys = {"Java", "Python", "Rust", "Go", "Kotlin", "TypeScript"};

        System.out.println("Bucket distribution for capacity = " + CAPACITY + ":");
        for (String key : keys) {
            int bucket = calculateBucket(key);
            System.out.printf("Key: %-12s | HashCode: %-11d | Bucket Index: %d%n", 
                              key, key.hashCode(), bucket);
        }
    }
}

