import java.util.Map;
import java.util.HashMap;

public class CollisionDetector {
    public static int countCollidingKeys(String[] keys, int capacity) {
        if (keys == null || keys.length == 0) return 0;
        Map<Integer, Integer> bucketCounts = new HashMap<>();
        for (String k : keys) {
            int h = (k == null) ? 0 : k.hashCode() ^ (k.hashCode() >>> 16);
            int bucket = (capacity - 1) & h;
            bucketCounts.put(bucket, bucketCounts.getOrDefault(bucket, 0) + 1);
        }
        int colliding = 0;
        for (String k : keys) {
            int h = (k == null) ? 0 : k.hashCode() ^ (k.hashCode() >>> 16);
            int bucket = (capacity - 1) & h;
            if (bucketCounts.get(bucket) > 1) {
                colliding++;
            }
        }
        return colliding;
    }
}

