public class MaxBucketChainFinder {
    public static int findMaxBucketChain(int[] values, int capacity) {
        if (values == null || values.length == 0) return 0;
        int[] bucketCounts = new int[capacity];
        int max = 0;
        for (int v : values) {
            int h = Integer.hashCode(v);
            int spread = h ^ (h >>> 16);
            int bucket = (capacity - 1) & spread;
            bucketCounts[bucket]++;
            if (bucketCounts[bucket] > max) {
                max = bucketCounts[bucket];
            }
        }
        return max;
    }
}
